@Component("coverage-handler")
@ProcessingGroup("coverage-processing-group")
public class CoverageEventHandler {
	
	// core constructor
	CoverageEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateCoverageEvent
     */
    @EventHandler
    public void handle( CreateCoverageEvent event) {
        entityManager.persist(new Coverage(event.getCoverageId(), event.getMemberId(), event.getGroupNumber(), event.getEffectiveDate(), event.getEndDate(), event.getPatient(), event.getPlan(), event.getClaims(), event.getAuthorizations(), event.getCoverageType()));
    }

    /*
     * @param	event UpdateCoverageEvent
     */
    @EventHandler
    public Coverage handle( UpdateCoverageEvent event) {
    	entityManager.merge(new Coverage(event.getCoverageId(), event.getMemberId(), event.getGroupNumber(), event.getEffectiveDate(), event.getEndDate(), event.getPatient(), event.getPlan(), event.getClaims(), event.getAuthorizations(), event.getCoverageType()));
    }
    
    /*
     * @param	event DeleteCoverageEvent
     */
    @EventHandler
    public void on( DeleteCoverageEvent event) {
    	Coverage entity = new Coverage();
   
    	// ------------------------------------------
    	// apply the CoverageId
    	// ------------------------------------------
    	entity.setCoverageId( event.getCoverageId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final CoverageRepository coverageEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(CoverageEventHandler.class.getName());

}
